mapper.select:
SELECT d.*, m.stock_in_type, m.supplier_name, m.customer_name, m.warehouse_id, m.purchaser_id, m.operator_name, m.status, m.approve_status, m.stock_in_time, m.source_order_no, m.remark as main_remark FROM mis_stock_in_detail d LEFT JOIN mis_stock_in m ON d.stock_in_id = m.id WHERE d.del_flag = '0'
AND m.stock_in_type = #{vo.stockInType}
AND m.supplier_name LIKE CONCAT('%', #{vo.supplierName}, '%')
AND m.customer_name LIKE CONCAT('%', #{vo.customerName}, '%')
AND m.warehouse_id = #{vo.warehouseId}
AND m.purchaser_id = #{vo.purchaserId}
AND m.operator_name LIKE CONCAT('%', #{vo.operatorName}, '%')
AND m.status = #{vo.status}
AND m.approve_status = #{vo.approveStatus}
AND m.source_order_no LIKE CONCAT('%', #{vo.sourceOrderNo}, '%')
AND d.goods_name LIKE CONCAT('%', #{vo.goodsName}, '%')
AND d.goods_code LIKE CONCAT('%', #{vo.goodsCode}, '%')
AND d.batch_no LIKE CONCAT('%', #{vo.batchNo}, '%')
AND m.stock_in_time >= #{vo.stockInTime_begin}
AND m.stock_in_time <= #{vo.stockInTime_end}
ORDER BY d.create_time DESC
